-- AMEX HOUSE V1.5.1 - três novas formações completas (360h cada)
begin;
alter table public.study_goals drop constraint if exists study_goals_academy_check; alter table public.study_goals add constraint study_goals_academy_check check(academy in('pentest','python','javascript','data','devops'));
alter table public.certificates drop constraint if exists certificates_academy_check; alter table public.certificates add constraint certificates_academy_check check(academy in('pentest','python','javascript','data','devops'));
alter table public.competencies drop constraint if exists competencies_academy_check; alter table public.competencies add constraint competencies_academy_check check(academy in('pentest','python','javascript','data','devops'));

create or replace function public.amex_course_academy(course_slug text) returns text language sql immutable set search_path=public as $$
 select case when course_slug=any(array['javascript-fundamentos','javascript-web-moderno','typescript-arquitetura','react-interfaces','node-backend','bancos-javascript','testes-javascript','fullstack-producao','javascript-projeto-senior']) then 'javascript' when course_slug=any(array['dados-fundamentos','sql-profissional','postgresql-modelagem','python-analise-dados','visualizacao-dados','estatistica-aplicada','engenharia-dados','analytics-bi','dados-projeto-senior']) then 'data' when course_slug=any(array['devops-fundamentos','linux-automacao','git-ci-cd','containers-docker','cloud-fundamentos','infraestrutura-codigo','kubernetes-plataforma','sre-observabilidade','devops-projeto-senior']) then 'devops' when course_slug like 'python-%' then 'python' else 'pentest' end
$$;
revoke all on function public.amex_course_academy(text) from public,anon;grant execute on function public.amex_course_academy(text) to authenticated;

create or replace function public.amex_admin_issue_certificate(target_user uuid,target_academy text,target_name text,target_hours integer)
returns text language plpgsql security definer set search_path=public as $$
declare actor uuid:=auth.uid();code text;lesson_total integer;lesson_done integer;quiz_total integer;quiz_done integer;
begin
 if not public.amex_is_staff(array['admin']) then raise exception 'Acesso negado' using errcode='42501';end if;
 if target_academy not in('pentest','python','javascript','data','devops') or length(trim(target_name)) not between 2 and 120 or target_hours not between 1 and 10000 then raise exception 'Dados inválidos' using errcode='22023';end if;
 select count(*),count(*) filter(where lp.status='completed') into lesson_total,lesson_done from public.lessons l join public.course_modules m on m.id=l.module_id join public.courses c on c.id=m.course_id left join public.lesson_progress lp on lp.lesson_id=l.id and lp.user_id=target_user where l.status='published' and c.status='published' and public.amex_course_academy(c.slug)=target_academy;
 if lesson_total=0 or lesson_done<>lesson_total then raise exception 'Formação incompleta: % de % aulas concluídas',lesson_done,lesson_total using errcode='22023';end if;
 select count(*),count(*) filter(where lp.quiz_passed=true) into quiz_total,quiz_done from public.amex_quiz_settings qs join public.lessons l on l.id=qs.lesson_id join public.course_modules m on m.id=l.module_id join public.courses c on c.id=m.course_id left join public.lesson_progress lp on lp.lesson_id=l.id and lp.user_id=target_user where qs.required and qs.status='published' and public.amex_course_academy(c.slug)=target_academy;
 if quiz_done<>quiz_total then raise exception 'Avaliações pendentes: % de % aprovadas',quiz_done,quiz_total using errcode='22023';end if;
 code:='AMEX-'||to_char(now(),'YYYY')||'-'||upper(substr(encode(gen_random_bytes(8),'hex'),1,12));
end$$;
revoke all on function public.amex_admin_issue_certificate(uuid,text,text,integer) from public,anon;grant execute on function public.amex_admin_issue_certificate(uuid,text,text,integer) to authenticated;

create or replace function public.amex_my_learning_insights(target_academy text) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare actor uuid:=auth.uid();attempts jsonb;skills jsonb;summary jsonb;recommendations jsonb;begin
 if actor is null or target_academy not in('pentest','python','javascript','data','devops') then raise exception 'Solicitação inválida' using errcode='22023';end if;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.submitted_at desc),'[]'::jsonb) into attempts from(
  select qa.attempt_number,qa.score,qa.passed,qa.started_at,qa.submitted_at,greatest(0,extract(epoch from(qa.submitted_at-qa.started_at))::integer) duration_seconds,
   qs.title quiz_title,l.title lesson_title,cr.title course_title
  from public.quiz_attempts qa join public.amex_quiz_settings qs on qs.id=qa.quiz_id join public.lessons l on l.id=qs.lesson_id join public.course_modules m on m.id=l.module_id join public.courses cr on cr.id=m.course_id
  where qa.user_id=actor and public.amex_course_academy(cr.slug)=target_academy limit 50
 )x;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.position),'[]'::jsonb) into skills from(
  select c.id,c.slug,c.title,c.description,c.position,count(distinct lc.lesson_id) lessons_total,
   count(distinct lp.lesson_id) filter(where lp.status='completed') lessons_completed,
   case when count(distinct lc.lesson_id)=0 then 0 else round(count(distinct lp.lesson_id) filter(where lp.status='completed')::numeric*100/count(distinct lc.lesson_id)) end percent
  from public.competencies c left join public.lesson_competencies lc on lc.competency_id=c.id left join public.lesson_progress lp on lp.lesson_id=lc.lesson_id and lp.user_id=actor
  where c.academy=target_academy group by c.id
 )x;
 select jsonb_build_object('attempts',count(*),'average_score',coalesce(round(avg(score),1),0),'approved',count(*) filter(where passed),'study_seconds',coalesce(sum((extract(epoch from(submitted_at-started_at))::integer)),0)) into summary
 from public.quiz_attempts qa join public.amex_quiz_settings qs on qs.id=qa.quiz_id join public.lessons l on l.id=qs.lesson_id join public.course_modules m on m.id=l.module_id join public.courses cr on cr.id=m.course_id
 where qa.user_id=actor and public.amex_course_academy(cr.slug)=target_academy;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.priority,x.title),'[]'::jsonb) into recommendations from(
  select 1 priority,'Reforce '||c.title title,'Conclua as aulas pendentes desta competência.' reason,c.slug reference from public.competencies c left join public.lesson_competencies lc on lc.competency_id=c.id left join public.lesson_progress lp on lp.lesson_id=lc.lesson_id and lp.user_id=actor where c.academy=target_academy group by c.id having count(distinct lp.lesson_id) filter(where lp.status='completed')<count(distinct lc.lesson_id)
  union all select 2,'Revise a última avaliação','Use seu histórico para identificar evolução entre tentativas.','quiz-history' where jsonb_array_length(attempts)>0
  limit 6
 )x;
 return jsonb_build_object('summary',summary,'attempts',attempts,'competencies',skills,'recommendations',recommendations,'generated_at',now());
end$$;
revoke all on function public.amex_my_learning_insights(text) from public,anon;grant execute on function public.amex_my_learning_insights(text) to authenticated;

commit;
